mapper.select:
select aa.id, aa.name, aa.protocol, aa.auth_type, aa.username, aa.update_by, su.username as update_by_name, aa.update_at, aa.user_tip, aa.password_tip, aa.weight, aa.state from asset_account aa left join sys_user su on aa.update_by = su.user_id where 1=1
and aa.id = #{params.id}
and aa.protocol = #{params.protocol}
and aa.state = #{params.state}
and aa.name like CONCAT('%', #{params.name}, '%')
